/**
 * Object storage operations used by profile image uploads.
 *
 * @module lib/storage/storage
 * @remarks
 * Keys are generated by the server and never reused, so every object is
 * immutable and can be cached forever by browsers and CDNs.
 */
import { DeleteObjectCommand, PutObjectCommand } from '@aws-sdk/client-s3'
import { env } from '@config/env'
import { getStorageClient } from '@lib/storage/client'
import { IMMUTABLE_CACHE_CONTROL } from '@lib/storage/constants'
import { storageError } from '@lib/storage/errors'

/**
 * Uploads bytes under `key`.
 *
 * @param key - Server-generated object key
 * @param bytes - Encoded file content
 * @param contentType - MIME type served back to clients
 * @throws {InfraError} `STORAGE_ERROR` when the backend rejects the upload
 */
export const putObject = async (
  key: string,
  bytes: Uint8Array,
  contentType: string
): Promise<void> => {
  try {
    await getStorageClient().send(
      new PutObjectCommand({
        Bucket: env.S3_BUCKET,
        Key: key,
        Body: bytes,
        ContentType: contentType,
        CacheControl: IMMUTABLE_CACHE_CONTROL,
      })
    )
  } catch (error) {
    throw storageError('put', key, error)
  }
}

/**
 * Deletes the object stored under `key` (a missing key is not an error).
 *
 * @param key - Object key to remove
 * @throws {InfraError} `STORAGE_ERROR` when the backend call fails
 */
export const deleteObject = async (key: string): Promise<void> => {
  try {
    await getStorageClient().send(
      new DeleteObjectCommand({ Bucket: env.S3_BUCKET, Key: key })
    )
  } catch (error) {
    throw storageError('delete', key, error)
  }
}

/**
 * Public URL of an object, served from `S3_PUBLIC_URL`.
 *
 * @param key - Object key
 * @returns Absolute URL clients can load directly
 */
export const publicUrl = (key: string): string =>
  `${(env.S3_PUBLIC_URL ?? '').replace(/\/+$/, '')}/${key}`
